Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], Pattern[n, Blank[]]]]], Pattern[p, Blank[]]], Pattern[x, Blank[Symbol]]] := ShowStep[748, "If \!\(\*RowBox[{RowBox[{\"IGtQ\", \"[\", RowBox[{\"n\", \",\", \"0\"}], \"]\"}], \"&&\", RowBox[{\"GtQ\", \"[\", RowBox[{\"p\", \",\", \"0\"}], \"]\"}], \"&&\", RowBox[{\"(\", RowBox[{RowBox[{\"IntegerQ\", \"[\", RowBox[{\"2\", \" \", \"p\"}], \"]\"}], \"||\", RowBox[{\"LtQ\", \"[\", RowBox[{RowBox[{\"Denominator\", \"[\", RowBox[{\"p\", \"+\", FractionBox[\"1\", \"n\"]}], \"]\"}], \",\", RowBox[{\"Denominator\", \"[\", \"p\", \"]\"}]}], \"]\"}]}], \")\"}]}]\)", "Integrate[((a) + (b)*(x)^(n))^(p), x]", "x*((a + b*x^n)^p/(n*p + 1)) + a*n*(p/(n*p + 1)) ⋆ Integrate[(a + b*x^n)^(p - 1), x]", Hold[Simp[x*((a + b*x^n)^p/(n*p + 1)), x] + Simp[a*n*(p/(n*p + 1)) ⋆ Int[(a + b*x^n)^(p - 1), x], x]]] /; FreeQ[{a, b}, x] && IGtQ[n, 0] && GtQ[p, 0] && (IntegerQ[2*p] || LtQ[Denominator[p + 1/n], Denominator[p]]) /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], Pattern[n, Blank[]]]]], Pattern[p, Blank[]]], Pattern[x, Blank[Symbol]]] := ShowStep[749, "If \!\(\*RowBox[{RowBox[{\"IGtQ\", \"[\", RowBox[{\"n\", \",\", \"0\"}], \"]\"}], \"&&\", RowBox[{\"LtQ\", \"[\", RowBox[{\"p\", \",\", RowBox[{\"-\", \"1\"}]}], \"]\"}], \"&&\", RowBox[{\"(\", RowBox[{RowBox[{\"IntegerQ\", \"[\", RowBox[{\"2\", \" \", \"p\"}], \"]\"}], \"||\", RowBox[{RowBox[{\"Denominator\", \"[\", RowBox[{\"p\", \"+\", FractionBox[\"1\", \"n\"]}], \"]\"}], \"<\", RowBox[{\"Denominator\", \"[\", \"p\", \"]\"}]}]}], \")\"}]}]\)", "Integrate[((a) + (b)*(x)^(n))^(p), x]", "(-x)*((a + b*x^n)^(p + 1)/(a*n*(p + 1))) + (n*(p + 1) + 1)/(a*n*(p + 1)) ⋆ Integrate[(a + b*x^n)^(p + 1), x]", Hold[Simp[(-x)*((a + b*x^n)^(p + 1)/(a*n*(p + 1))), x] + Simp[(n*(p + 1) + 1)/(a*n*(p + 1)) ⋆ Int[(a + b*x^n)^(p + 1), x], x]]] /; FreeQ[{a, b}, x] && IGtQ[n, 0] && LtQ[p, -1] && (IntegerQ[2*p] || Denominator[p + 1/n] < Denominator[p]) /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 3]]], -1], Pattern[x, Blank[Symbol]]] := ShowStep[750, "", "Integrate[((a) + (b)*(x)^3)^(-1), x]", "1/(3*(a^3^(-1))^2) ⋆ Integrate[1/(a^3^(-1) + b^3^(-1)*x), x] + 1/(3*(a^3^(-1))^2) ⋆ Integrate[(2*a^3^(-1) - b^3^(-1)*x)/((a^3^(-1))^2 - a^3^(-1)*b^3^(-1)*x + (b^3^(-1))^2*x^2), x]", Hold[Simp[1/(3*Rt[a, 3]^2) ⋆ Int[1/(Rt[a, 3] + Rt[b, 3]*x), x], x] + Simp[1/(3*Rt[a, 3]^2) ⋆ Int[(2*Rt[a, 3] - Rt[b, 3]*x)/(Rt[a, 3]^2 - Rt[a, 3]*Rt[b, 3]*x + Rt[b, 3]^2*x^2), x], x]]] /; FreeQ[{a, b}, x] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], Pattern[n, Blank[]]]]], -1], Pattern[x, Blank[Symbol]]] := Module[{r = Numerator[Rt[a/b, n]], s = Denominator[Rt[a/b, n]], k, u}, ShowStep[751, "If \!\(\*RowBox[{RowBox[{\"IGtQ\", \"[\", RowBox[{FractionBox[RowBox[{\"n\", \"-\", \"3\"}], \"2\"], \",\", \"0\"}], \"]\"}], \"&&\", RowBox[{\"PosQ\", \"[\", FractionBox[\"a\", \"b\"], \"]\"}]}]\) let \!\(\*RowBox[{\"{\", RowBox[{RowBox[{\"r\", \"=\", RowBox[{\"Numerator\", \"[\", SuperscriptBox[RowBox[{\"(\", FractionBox[\"a\", \"b\"], \")\"}], FractionBox[\"1\", \"n\"]], \"]\"}]}], \",\", RowBox[{\"s\", \"=\", RowBox[{\"Denominator\", \"[\", SuperscriptBox[RowBox[{\"(\", FractionBox[\"a\", \"b\"], \")\"}], FractionBox[\"1\", \"n\"]], \"]\"}]}], \",\", \"k\", \",\", \"u\"}], \"}\"}]\), then", "Integrate[((a) + (b)*(x)^(n))^(-1), x]", "u = Integrate[(r - s*Cos[(2*k - 1)*(Pi/n)]*x)/(r^2 - 2*r*s*Cos[(2*k - 1)*(Pi/n)]*x + s^2*x^2), x]; r/(a*n) ⋆ Integrate[1/(r + s*x), x] + 2*(r/(a*n)) ⋆ Sum[u, {k, 1, (n - 1)/2}]", Hold[Simp[u = Int[(r - s*Cos[(2*k - 1)*(Pi/n)]*x)/(r^2 - 2*r*s*Cos[(2*k - 1)*(Pi/n)]*x + s^2*x^2), x]; r/(a*n) ⋆ Int[1/(r + s*x), x] + 2*(r/(a*n)) ⋆ Sum[u, {k, 1, (n - 1)/2}], x]]]] /; FreeQ[{a, b}, x] && IGtQ[(n - 3)/2, 0] && PosQ[a/b] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], Pattern[n, Blank[]]]]], -1], Pattern[x, Blank[Symbol]]] := Module[{r = Numerator[Rt[-a/b, n]], s = Denominator[Rt[-a/b, n]], k, u}, ShowStep[752, "If \!\(\*RowBox[{RowBox[{\"IGtQ\", \"[\", RowBox[{FractionBox[RowBox[{\"n\", \"-\", \"3\"}], \"2\"], \",\", \"0\"}], \"]\"}], \"&&\", RowBox[{\"NegQ\", \"[\", FractionBox[\"a\", \"b\"], \"]\"}]}]\) let \!\(\*RowBox[{\"{\", RowBox[{RowBox[{\"r\", \"=\", RowBox[{\"Numerator\", \"[\", SuperscriptBox[RowBox[{\"(\", RowBox[{\"-\", FractionBox[\"a\", \"b\"]}], \")\"}], FractionBox[\"1\", \"n\"]], \"]\"}]}], \",\", RowBox[{\"s\", \"=\", RowBox[{\"Denominator\", \"[\", SuperscriptBox[RowBox[{\"(\", RowBox[{\"-\", FractionBox[\"a\", \"b\"]}], \")\"}], FractionBox[\"1\", \"n\"]], \"]\"}]}], \",\", \"k\", \",\", \"u\"}], \"}\"}]\), then", "Integrate[((a) + (b)*(x)^(n))^(-1), x]", "u = Integrate[(r + s*Cos[(2*k - 1)*(Pi/n)]*x)/(r^2 + 2*r*s*Cos[(2*k - 1)*(Pi/n)]*x + s^2*x^2), x]; r/(a*n) ⋆ Integrate[1/(r - s*x), x] + 2*(r/(a*n)) ⋆ Sum[u, {k, 1, (n - 1)/2}]", Hold[Simp[u = Int[(r + s*Cos[(2*k - 1)*(Pi/n)]*x)/(r^2 + 2*r*s*Cos[(2*k - 1)*(Pi/n)]*x + s^2*x^2), x]; r/(a*n) ⋆ Int[1/(r - s*x), x] + 2*(r/(a*n)) ⋆ Sum[u, {k, 1, (n - 1)/2}], x]]]] /; FreeQ[{a, b}, x] && IGtQ[(n - 3)/2, 0] && NegQ[a/b] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], Pattern[n, Blank[]]]]], -1], Pattern[x, Blank[Symbol]]] := Module[{r = Numerator[Rt[a/b, n]], s = Denominator[Rt[a/b, n]], k, u, v}, ShowStep[753, "If \!\(\*RowBox[{RowBox[{\"IGtQ\", \"[\", RowBox[{FractionBox[RowBox[{\"n\", \"-\", \"2\"}], \"4\"], \",\", \"0\"}], \"]\"}], \"&&\", RowBox[{\"PosQ\", \"[\", FractionBox[\"a\", \"b\"], \"]\"}]}]\) let \!\(\*RowBox[{\"{\", RowBox[{RowBox[{\"r\", \"=\", RowBox[{\"Numerator\", \"[\", SuperscriptBox[RowBox[{\"(\", FractionBox[\"a\", \"b\"], \")\"}], FractionBox[\"1\", \"n\"]], \"]\"}]}], \",\", RowBox[{\"s\", \"=\", RowBox[{\"Denominator\", \"[\", SuperscriptBox[RowBox[{\"(\", FractionBox[\"a\", \"b\"], \")\"}], FractionBox[\"1\", \"n\"]], \"]\"}]}], \",\", \"k\", \",\", \"u\", \",\", \"v\"}], \"}\"}]\), then", "Integrate[((a) + (b)*(x)^(n))^(-1), x]", "u = Integrate[(r - s*Cos[(2*k - 1)*(Pi/n)]*x)/(r^2 - 2*r*s*Cos[(2*k - 1)*(Pi/n)]*x + s^2*x^2), x] + Integrate[(r + s*Cos[(2*k - 1)*(Pi/n)]*x)/(r^2 + 2*r*s*Cos[(2*k - 1)*(Pi/n)]*x + s^2*x^2), x]; 2*(r^2/(a*n)) ⋆ Integrate[1/(r^2 + s^2*x^2), x] + 2*(r/(a*n)) ⋆ Sum[u, {k, 1, (n - 2)/4}]", Hold[Simp[u = Int[(r - s*Cos[(2*k - 1)*(Pi/n)]*x)/(r^2 - 2*r*s*Cos[(2*k - 1)*(Pi/n)]*x + s^2*x^2), x] + Int[(r + s*Cos[(2*k - 1)*(Pi/n)]*x)/(r^2 + 2*r*s*Cos[(2*k - 1)*(Pi/n)]*x + s^2*x^2), x]; 2*(r^2/(a*n)) ⋆ Int[1/(r^2 + s^2*x^2), x] + 2*(r/(a*n)) ⋆ Sum[u, {k, 1, (n - 2)/4}], x]]]] /; FreeQ[{a, b}, x] && IGtQ[(n - 2)/4, 0] && PosQ[a/b] /; True
