Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 4]]], -1], Pattern[x, Blank[Symbol]]] := With[{r = Numerator[Rt[a/b, 2]], s = Denominator[Rt[a/b, 2]]}, ShowStep[755, "If \!\(\*RowBox[{RowBox[{\"GtQ\", \"[\", RowBox[{FractionBox[\"a\", \"b\"], \",\", \"0\"}], \"]\"}], \"||\", RowBox[{\"(\", RowBox[{RowBox[{\"PosQ\", \"[\", FractionBox[\"a\", \"b\"], \"]\"}], \"&&\", RowBox[{\"AtomQ\", \"[\", RowBox[{\"SplitProduct\", \"[\", RowBox[{\"SumBaseQ\", \",\", \"a\"}], \"]\"}], \"]\"}], \"&&\", RowBox[{\"AtomQ\", \"[\", RowBox[{\"SplitProduct\", \"[\", RowBox[{\"SumBaseQ\", \",\", \"b\"}], \"]\"}], \"]\"}]}], \")\"}]}]\) let \!\(\*RowBox[{\"{\", RowBox[{RowBox[{\"r\", \"=\", RowBox[{\"Numerator\", \"[\", SqrtBox[FractionBox[\"a\", \"b\"]], \"]\"}]}], \",\", RowBox[{\"s\", \"=\", RowBox[{\"Denominator\", \"[\", SqrtBox[FractionBox[\"a\", \"b\"]], \"]\"}]}]}], \"}\"}]\), then", "Integrate[((a) + (b)*(x)^4)^(-1), x]", "1/(2*r) ⋆ Integrate[(r - s*x^2)/(a + b*x^4), x] + 1/(2*r) ⋆ Integrate[(r + s*x^2)/(a + b*x^4), x]", Hold[Simp[1/(2*r) ⋆ Int[(r - s*x^2)/(a + b*x^4), x], x] + Simp[1/(2*r) ⋆ Int[(r + s*x^2)/(a + b*x^4), x], x]]]] /; FreeQ[{a, b}, x] && (GtQ[a/b, 0] || (PosQ[a/b] && AtomQ[SplitProduct[SumBaseQ, a]] && AtomQ[SplitProduct[SumBaseQ, b]])) /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 4]]], -1], Pattern[x, Blank[Symbol]]] := With[{r = Numerator[Rt[-a/b, 2]], s = Denominator[Rt[-a/b, 2]]}, ShowStep[756, "If \!\(\*RowBox[{\"!\", RowBox[{\"GtQ\", \"[\", RowBox[{FractionBox[\"a\", \"b\"], \",\", \"0\"}], \"]\"}]}]\) let \!\(\*RowBox[{\"{\", RowBox[{RowBox[{\"r\", \"=\", RowBox[{\"Numerator\", \"[\", SqrtBox[RowBox[{\"-\", FractionBox[\"a\", \"b\"]}]], \"]\"}]}], \",\", RowBox[{\"s\", \"=\", RowBox[{\"Denominator\", \"[\", SqrtBox[RowBox[{\"-\", FractionBox[\"a\", \"b\"]}]], \"]\"}]}]}], \"}\"}]\), then", "Integrate[((a) + (b)*(x)^4)^(-1), x]", "r/(2*a) ⋆ Integrate[1/(r - s*x^2), x] + r/(2*a) ⋆ Integrate[1/(r + s*x^2), x]", Hold[Simp[r/(2*a) ⋆ Int[1/(r - s*x^2), x], x] + Simp[r/(2*a) ⋆ Int[1/(r + s*x^2), x], x]]]] /; FreeQ[{a, b}, x] &&  !GtQ[a/b, 0] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], Pattern[n, Blank[]]]]], -1], Pattern[x, Blank[Symbol]]] := With[{r = Numerator[Rt[a/b, 4]], s = Denominator[Rt[a/b, 4]]}, ShowStep[757, "If \!\(\*RowBox[{RowBox[{\"IGtQ\", \"[\", RowBox[{FractionBox[\"n\", \"4\"], \",\", \"1\"}], \"]\"}], \"&&\", RowBox[{\"GtQ\", \"[\", RowBox[{FractionBox[\"a\", \"b\"], \",\", \"0\"}], \"]\"}]}]\) let \!\(\*RowBox[{\"{\", RowBox[{RowBox[{\"r\", \"=\", RowBox[{\"Numerator\", \"[\", SuperscriptBox[RowBox[{\"(\", FractionBox[\"a\", \"b\"], \")\"}], FractionBox[\"1\", \"4\"]], \"]\"}]}], \",\", RowBox[{\"s\", \"=\", RowBox[{\"Denominator\", \"[\", SuperscriptBox[RowBox[{\"(\", FractionBox[\"a\", \"b\"], \")\"}], FractionBox[\"1\", \"4\"]], \"]\"}]}]}], \"}\"}]\), then", "Integrate[((a) + (b)*(x)^(n))^(-1), x]", "r/(2*Sqrt[2]*a) ⋆ Integrate[(Sqrt[2]*r - s*x^(n/4))/(r^2 - Sqrt[2]*r*s*x^(n/4) + s^2*x^(n/2)), x] + r/(2*Sqrt[2]*a) ⋆ Integrate[(Sqrt[2]*r + s*x^(n/4))/(r^2 + Sqrt[2]*r*s*x^(n/4) + s^2*x^(n/2)), x]", Hold[Simp[r/(2*Sqrt[2]*a) ⋆ Int[(Sqrt[2]*r - s*x^(n/4))/(r^2 - Sqrt[2]*r*s*x^(n/4) + s^2*x^(n/2)), x], x] + Simp[r/(2*Sqrt[2]*a) ⋆ Int[(Sqrt[2]*r + s*x^(n/4))/(r^2 + Sqrt[2]*r*s*x^(n/4) + s^2*x^(n/2)), x], x]]]] /; FreeQ[{a, b}, x] && IGtQ[n/4, 1] && GtQ[a/b, 0] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], Pattern[n, Blank[]]]]], -1], Pattern[x, Blank[Symbol]]] := With[{r = Numerator[Rt[-a/b, 2]], s = Denominator[Rt[-a/b, 2]]}, ShowStep[758, "If \!\(\*RowBox[{RowBox[{\"IGtQ\", \"[\", RowBox[{FractionBox[\"n\", \"4\"], \",\", \"1\"}], \"]\"}], \"&&\", RowBox[{\"!\", RowBox[{\"GtQ\", \"[\", RowBox[{FractionBox[\"a\", \"b\"], \",\", \"0\"}], \"]\"}]}]}]\) let \!\(\*RowBox[{\"{\", RowBox[{RowBox[{\"r\", \"=\", RowBox[{\"Numerator\", \"[\", SqrtBox[RowBox[{\"-\", FractionBox[\"a\", \"b\"]}]], \"]\"}]}], \",\", RowBox[{\"s\", \"=\", RowBox[{\"Denominator\", \"[\", SqrtBox[RowBox[{\"-\", FractionBox[\"a\", \"b\"]}]], \"]\"}]}]}], \"}\"}]\), then", "Integrate[((a) + (b)*(x)^(n))^(-1), x]", "r/(2*a) ⋆ Integrate[1/(r - s*x^(n/2)), x] + r/(2*a) ⋆ Integrate[1/(r + s*x^(n/2)), x]", Hold[Simp[r/(2*a) ⋆ Int[1/(r - s*x^(n/2)), x], x] + Simp[r/(2*a) ⋆ Int[1/(r + s*x^(n/2)), x], x]]]] /; FreeQ[{a, b}, x] && IGtQ[n/4, 1] &&  !GtQ[a/b, 0] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 3]]], Rational[-1, 2]], Pattern[x, Blank[Symbol]]] := With[{r = Numer[Rt[b/a, 3]], s = Denom[Rt[b/a, 3]]}, ShowStep[759, "If \!\(\*RowBox[{\"PosQ\", \"[\", \"a\", \"]\"}]\) let \!\(\*RowBox[{\"{\", RowBox[{RowBox[{\"r\", \"=\", RowBox[{\"Numer\", \"[\", SuperscriptBox[RowBox[{\"(\", FractionBox[\"b\", \"a\"], \")\"}], FractionBox[\"1\", \"3\"]], \"]\"}]}], \",\", RowBox[{\"s\", \"=\", RowBox[{\"Denom\", \"[\", SuperscriptBox[RowBox[{\"(\", FractionBox[\"b\", \"a\"], \")\"}], FractionBox[\"1\", \"3\"]], \"]\"}]}]}], \"}\"}]\), then", "Integrate[1/Sqrt[(a) + (b)*(x)^3], x]", "2*Sqrt[2 + Sqrt[3]]*(s + r*x)*(Sqrt[(s^2 - r*s*x + r^2*x^2)/((1 + Sqrt[3])*s + r*x)^2]/(3^(1/4)*r*Sqrt[a + b*x^3]*Sqrt[s*((s + r*x)/((1 + Sqrt[3])*s + r*x)^2)]))*EllipticF[ArcSin[((1 - Sqrt[3])*s + r*x)/((1 + Sqrt[3])*s + r*x)], -7 - 4*Sqrt[3]]", Hold[Simp[2*Sqrt[2 + Sqrt[3]]*(s + r*x)*(Sqrt[(s^2 - r*s*x + r^2*x^2)/((1 + Sqrt[3])*s + r*x)^2]/(3^(1/4)*r*Sqrt[a + b*x^3]*Sqrt[s*((s + r*x)/((1 + Sqrt[3])*s + r*x)^2)]))*EllipticF[ArcSin[((1 - Sqrt[3])*s + r*x)/((1 + Sqrt[3])*s + r*x)], -7 - 4*Sqrt[3]], x]]]] /; FreeQ[{a, b}, x] && PosQ[a] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 3]]], Rational[-1, 2]], Pattern[x, Blank[Symbol]]] := With[{r = Numer[Rt[b/a, 3]], s = Denom[Rt[b/a, 3]]}, ShowStep[760, "If \!\(\*RowBox[{\"NegQ\", \"[\", \"a\", \"]\"}]\) let \!\(\*RowBox[{\"{\", RowBox[{RowBox[{\"r\", \"=\", RowBox[{\"Numer\", \"[\", SuperscriptBox[RowBox[{\"(\", FractionBox[\"b\", \"a\"], \")\"}], FractionBox[\"1\", \"3\"]], \"]\"}]}], \",\", RowBox[{\"s\", \"=\", RowBox[{\"Denom\", \"[\", SuperscriptBox[RowBox[{\"(\", FractionBox[\"b\", \"a\"], \")\"}], FractionBox[\"1\", \"3\"]], \"]\"}]}]}], \"}\"}]\), then", "Integrate[1/Sqrt[(a) + (b)*(x)^3], x]", "2*Sqrt[2 - Sqrt[3]]*(s + r*x)*(Sqrt[(s^2 - r*s*x + r^2*x^2)/((1 - Sqrt[3])*s + r*x)^2]/(3^(1/4)*r*Sqrt[a + b*x^3]*Sqrt[(-s)*((s + r*x)/((1 - Sqrt[3])*s + r*x)^2)]))*EllipticF[ArcSin[((1 + Sqrt[3])*s + r*x)/((1 - Sqrt[3])*s + r*x)], -7 + 4*Sqrt[3]]", Hold[Simp[2*Sqrt[2 - Sqrt[3]]*(s + r*x)*(Sqrt[(s^2 - r*s*x + r^2*x^2)/((1 - Sqrt[3])*s + r*x)^2]/(3^(1/4)*r*Sqrt[a + b*x^3]*Sqrt[(-s)*((s + r*x)/((1 - Sqrt[3])*s + r*x)^2)]))*EllipticF[ArcSin[((1 + Sqrt[3])*s + r*x)/((1 - Sqrt[3])*s + r*x)], -7 + 4*Sqrt[3]], x]]]] /; FreeQ[{a, b}, x] && NegQ[a] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 4]]], Rational[-1, 2]], Pattern[x, Blank[Symbol]]] := With[{q = Rt[b/a, 4]}, ShowStep[761, "If \!\(\*RowBox[{\"PosQ\", \"[\", FractionBox[\"b\", \"a\"], \"]\"}]\) let \!\(\*RowBox[{\"q\", \"=\", SuperscriptBox[RowBox[{\"(\", FractionBox[\"b\", \"a\"], \")\"}], FractionBox[\"1\", \"4\"]]}]\), then", "Integrate[1/Sqrt[(a) + (b)*(x)^4], x]", "(1 + q^2*x^2)*(Sqrt[(a + b*x^4)/(a*(1 + q^2*x^2)^2)]/(2*q*Sqrt[a + b*x^4]))*EllipticF[2*ArcTan[q*x], 1/2]", Hold[Simp[(1 + q^2*x^2)*(Sqrt[(a + b*x^4)/(a*(1 + q^2*x^2)^2)]/(2*q*Sqrt[a + b*x^4]))*EllipticF[2*ArcTan[q*x], 1/2], x]]]] /; FreeQ[{a, b}, x] && PosQ[b/a] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 4]]], Rational[-1, 2]], Pattern[x, Blank[Symbol]]] := ShowStep[762, "If \!\(\*RowBox[{RowBox[{\"NegQ\", \"[\", FractionBox[\"b\", \"a\"], \"]\"}], \"&&\", RowBox[{\"GtQ\", \"[\", RowBox[{\"a\", \",\", \"0\"}], \"]\"}]}]\)", "Integrate[1/Sqrt[(a) + (b)*(x)^4], x]", "(1/(Sqrt[a]*(-b/a)^4^(-1)))*EllipticF[ArcSin[(-b/a)^4^(-1)*x], -1]", Hold[Simp[(1/(Sqrt[a]*Rt[-b/a, 4]))*EllipticF[ArcSin[Rt[-b/a, 4]*x], -1], x]]] /; FreeQ[{a, b}, x] && NegQ[b/a] && GtQ[a, 0] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 4]]], Rational[-1, 2]], Pattern[x, Blank[Symbol]]] := With[{q = Rt[(-a)*b, 2]}, ShowStep[763, "If \!\(\*RowBox[{RowBox[{\"LtQ\", \"[\", RowBox[{\"a\", \",\", \"0\"}], \"]\"}], \"&&\", RowBox[{\"GtQ\", \"[\", RowBox[{\"b\", \",\", \"0\"}], \"]\"}]}]\) let \!\(\*RowBox[{\"q\", \"=\", SqrtBox[RowBox[{RowBox[{\"-\", \"a\"}], \" \", \"b\"}]]}]\), then if \!\(\*RowBox[{\"IntegerQ\", \"[\", \"q\", \"]\"}]\)", "Integrate[1/Sqrt[(a) + (b)*(x)^4], x]", "Sqrt[-a + q*x^2]*(Sqrt[(a + q*x^2)/q]/(Sqrt[2]*Sqrt[-a]*Sqrt[a + b*x^4]))*EllipticF[ArcSin[x/Sqrt[(a + q*x^2)/(2*q)]], 1/2]", Hold[Simp[Sqrt[-a + q*x^2]*(Sqrt[(a + q*x^2)/q]/(Sqrt[2]*Sqrt[-a]*Sqrt[a + b*x^4]))*EllipticF[ArcSin[x/Sqrt[(a + q*x^2)/(2*q)]], 1/2], x]]] /; IntegerQ[q]] /; FreeQ[{a, b}, x] && LtQ[a, 0] && GtQ[b, 0] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 4]]], Rational[-1, 2]], Pattern[x, Blank[Symbol]]] := With[{q = Rt[(-a)*b, 2]}, ShowStep[764, "If \!\(\*RowBox[{RowBox[{\"LtQ\", \"[\", RowBox[{\"a\", \",\", \"0\"}], \"]\"}], \"&&\", RowBox[{\"GtQ\", \"[\", RowBox[{\"b\", \",\", \"0\"}], \"]\"}]}]\) let \!\(\*RowBox[{\"q\", \"=\", SqrtBox[RowBox[{RowBox[{\"-\", \"a\"}], \" \", \"b\"}]]}]\), then", "Integrate[1/Sqrt[(a) + (b)*(x)^4], x]", "Sqrt[(a - q*x^2)/(a + q*x^2)]*(Sqrt[(a + q*x^2)/q]/(Sqrt[2]*Sqrt[a + b*x^4]*Sqrt[a/(a + q*x^2)]))*EllipticF[ArcSin[x/Sqrt[(a + q*x^2)/(2*q)]], 1/2]", Hold[Simp[Sqrt[(a - q*x^2)/(a + q*x^2)]*(Sqrt[(a + q*x^2)/q]/(Sqrt[2]*Sqrt[a + b*x^4]*Sqrt[a/(a + q*x^2)]))*EllipticF[ArcSin[x/Sqrt[(a + q*x^2)/(2*q)]], 1/2], x]]]] /; FreeQ[{a, b}, x] && LtQ[a, 0] && GtQ[b, 0] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 4]]], Rational[-1, 2]], Pattern[x, Blank[Symbol]]] := ShowStep[765, "If \!\(\*RowBox[{RowBox[{\"NegQ\", \"[\", FractionBox[\"b\", \"a\"], \"]\"}], \"&&\", RowBox[{\"!\", RowBox[{\"GtQ\", \"[\", RowBox[{\"a\", \",\", \"0\"}], \"]\"}]}]}]\)", "Integrate[1/Sqrt[(a) + (b)*(x)^4], x]", "Sqrt[1 + b*(x^4/a)]/Sqrt[a + b*x^4] ⋆ Integrate[1/Sqrt[1 + b*(x^4/a)], x]", Hold[Simp[Sqrt[1 + b*(x^4/a)]/Sqrt[a + b*x^4] ⋆ Int[1/Sqrt[1 + b*(x^4/a)], x], x]]] /; FreeQ[{a, b}, x] && NegQ[b/a] &&  !GtQ[a, 0] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 6]]], Rational[-1, 2]], Pattern[x, Blank[Symbol]]] := With[{r = Numer[Rt[b/a, 3]], s = Denom[Rt[b/a, 3]]}, ShowStep[766, "Let \!\(\*RowBox[{\"{\", RowBox[{RowBox[{\"r\", \"=\", RowBox[{\"Numer\", \"[\", SuperscriptBox[RowBox[{\"(\", FractionBox[\"b\", \"a\"], \")\"}], FractionBox[\"1\", \"3\"]], \"]\"}]}], \",\", RowBox[{\"s\", \"=\", RowBox[{\"Denom\", \"[\", SuperscriptBox[RowBox[{\"(\", FractionBox[\"b\", \"a\"], \")\"}], FractionBox[\"1\", \"3\"]], \"]\"}]}]}], \"}\"}]\), then", "Integrate[1/Sqrt[(a) + (b)*(x)^6], x]", "x*(s + r*x^2)*(Sqrt[(s^2 - r*s*x^2 + r^2*x^4)/(s + (1 + Sqrt[3])*r*x^2)^2]/(2*3^(1/4)*s*Sqrt[a + b*x^6]*Sqrt[r*x^2*((s + r*x^2)/(s + (1 + Sqrt[3])*r*x^2)^2)]))*EllipticF[ArcCos[(s + (1 - Sqrt[3])*r*x^2)/(s + (1 + Sqrt[3])*r*x^2)], (2 + Sqrt[3])/4]", Hold[Simp[x*(s + r*x^2)*(Sqrt[(s^2 - r*s*x^2 + r^2*x^4)/(s + (1 + Sqrt[3])*r*x^2)^2]/(2*3^(1/4)*s*Sqrt[a + b*x^6]*Sqrt[r*x^2*((s + r*x^2)/(s + (1 + Sqrt[3])*r*x^2)^2)]))*EllipticF[ArcCos[(s + (1 - Sqrt[3])*r*x^2)/(s + (1 + Sqrt[3])*r*x^2)], (2 + Sqrt[3])/4], x]]]] /; FreeQ[{a, b}, x] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 8]]], Rational[-1, 2]], Pattern[x, Blank[Symbol]]] := ShowStep[767, "", "Integrate[1/Sqrt[(a) + (b)*(x)^8], x]", "1/2 ⋆ Integrate[(1 - (b/a)^4^(-1)*x^2)/Sqrt[a + b*x^8], x] + 1/2 ⋆ Integrate[(1 + (b/a)^4^(-1)*x^2)/Sqrt[a + b*x^8], x]", Hold[Simp[1/2 ⋆ Int[(1 - Rt[b/a, 4]*x^2)/Sqrt[a + b*x^8], x], x] + Simp[1/2 ⋆ Int[(1 + Rt[b/a, 4]*x^2)/Sqrt[a + b*x^8], x], x]]] /; FreeQ[{a, b}, x] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 4]]], Rational[-3, 4]], Pattern[x, Blank[Symbol]]] := ShowStep[768, "", "Integrate[((a) + (b)*(x)^4)^(-3/4), x]", "x^3*((1 + a/(b*x^4))^(3/4)/(a + b*x^4)^(3/4)) ⋆ Integrate[1/(x^3*(1 + a/(b*x^4))^(3/4)), x]", Hold[Simp[x^3*((1 + a/(b*x^4))^(3/4)/(a + b*x^4)^(3/4)) ⋆ Int[1/(x^3*(1 + a/(b*x^4))^(3/4)), x], x]]] /; FreeQ[{a, b}, x] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 3]]], Rational[-1, 3]], Pattern[x, Blank[Symbol]]] := ShowStep[769, "", "Integrate[((a) + (b)*(x)^3)^(-1/3), x]", "ArcTan[(1 + 2*b^3^(-1)*(x/(a + b*x^3)^(1/3)))/Sqrt[3]]/(Sqrt[3]*b^3^(-1)) - Log[(a + b*x^3)^(1/3) - b^3^(-1)*x]/(2*b^3^(-1))", Hold[Simp[ArcTan[(1 + 2*Rt[b, 3]*(x/(a + b*x^3)^(1/3)))/Sqrt[3]]/(Sqrt[3]*Rt[b, 3]), x] - Simp[Log[(a + b*x^3)^(1/3) - Rt[b, 3]*x]/(2*Rt[b, 3]), x]]] /; FreeQ[{a, b}, x] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], Pattern[n, Blank[]]]]], Pattern[p, Blank[]]], Pattern[x, Blank[Symbol]]] := ShowStep[770, "If \!\(\*RowBox[{RowBox[{\"IGtQ\", \"[\", RowBox[{\"n\", \",\", \"0\"}], \"]\"}], \"&&\", RowBox[{\"LtQ\", \"[\", RowBox[{RowBox[{\"-\", \"1\"}], \",\", \"p\", \",\", \"0\"}], \"]\"}], \"&&\", RowBox[{\"NeQ\", \"[\", RowBox[{\"p\", \",\", RowBox[{\"-\", FractionBox[\"1\", \"2\"]}]}], \"]\"}], \"&&\", RowBox[{\"IntegerQ\", \"[\", RowBox[{\"p\", \"+\", FractionBox[\"1\", \"n\"]}], \"]\"}]}]\)", "Integrate[((a) + (b)*(x)^(n))^(p), x]", "a^(p + 1/n) ⋆ Subst[Integrate[1/(1 - b*x^n)^(p + 1/n + 1), x], x, x/(a + b*x^n)^(1/n)]", Hold[Simp[a^(p + 1/n) ⋆ Subst[Int[1/(1 - b*x^n)^(p + 1/n + 1), x], x, x/(a + b*x^n)^(1/n)], x]]] /; FreeQ[{a, b}, x] && IGtQ[n, 0] && LtQ[-1, p, 0] && NeQ[p, -2^(-1)] && IntegerQ[p + 1/n] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], Pattern[n, Blank[]]]]], Pattern[p, Blank[]]], Pattern[x, Blank[Symbol]]] := ShowStep[771, "If \!\(\*RowBox[{RowBox[{\"IGtQ\", \"[\", RowBox[{\"n\", \",\", \"0\"}], \"]\"}], \"&&\", RowBox[{\"LtQ\", \"[\", RowBox[{RowBox[{\"-\", \"1\"}], \",\", \"p\", \",\", \"0\"}], \"]\"}], \"&&\", RowBox[{\"NeQ\", \"[\", RowBox[{\"p\", \",\", RowBox[{\"-\", FractionBox[\"1\", \"2\"]}]}], \"]\"}], \"&&\", RowBox[{\"LtQ\", \"[\", RowBox[{RowBox[{\"Denominator\", \"[\", RowBox[{\"p\", \"+\", FractionBox[\"1\", \"n\"]}], \"]\"}], \",\", RowBox[{\"Denominator\", \"[\", \"p\", \"]\"}]}], \"]\"}]}]\)", "Integrate[((a) + (b)*(x)^(n))^(p), x]", "(a/(a + b*x^n))^(p + 1/n)*(a + b*x^n)^(p + 1/n) ⋆ Subst[Integrate[1/(1 - b*x^n)^(p + 1/n + 1), x], x, x/(a + b*x^n)^(1/n)]", Hold[Simp[(a/(a + b*x^n))^(p + 1/n)*(a + b*x^n)^(p + 1/n) ⋆ Subst[Int[1/(1 - b*x^n)^(p + 1/n + 1), x], x, x/(a + b*x^n)^(1/n)], x]]] /; FreeQ[{a, b}, x] && IGtQ[n, 0] && LtQ[-1, p, 0] && NeQ[p, -2^(-1)] && LtQ[Denominator[p + 1/n], Denominator[p]] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], Pattern[n, Blank[]]]]], Pattern[p, Blank[]]], Pattern[x, Blank[Symbol]]] := ShowStep[772, "If \!\(\*RowBox[{RowBox[{\"ILtQ\", \"[\", RowBox[{\"n\", \",\", \"0\"}], \"]\"}], \"&&\", RowBox[{\"IntegerQ\", \"[\", \"p\", \"]\"}]}]\)", "Integrate[((a) + (b)*(x)^(n))^(p), x]", "Integrate[x^(n*p)*(b + a/x^n)^p, x]", Hold[Int[x^(n*p)*(b + a/x^n)^p, x]]] /; FreeQ[{a, b}, x] && ILtQ[n, 0] && IntegerQ[p] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], Pattern[n, Blank[]]]]], Pattern[p, Blank[]]], Pattern[x, Blank[Symbol]]] := ShowStep[773, "If \!\(\*RowBox[{RowBox[{\"ILtQ\", \"[\", RowBox[{\"n\", \",\", \"0\"}], \"]\"}], \"&&\", RowBox[{\"!\", RowBox[{\"IntegerQ\", \"[\", \"p\", \"]\"}]}]}]\)", "Integrate[((a) + (b)*(x)^(n))^(p), x]", "-Subst[Integrate[(a + b/x^n)^p/x^2, x], x, 1/x]", Hold[-Subst[Int[(a + b/x^n)^p/x^2, x], x, 1/x]]] /; FreeQ[{a, b, p}, x] && ILtQ[n, 0] &&  !IntegerQ[p] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], Pattern[n, Blank[]]]]], Pattern[p, Blank[]]], Pattern[x, Blank[Symbol]]] := With[{k = Denominator[n]}, ShowStep[774, "If \!\(\*RowBox[{\"FractionQ\", \"[\", \"n\", \"]\"}]\) let \!\(\*RowBox[{\"k\", \"=\", RowBox[{\"Denominator\", \"[\", \"n\", \"]\"}]}]\), then", "Integrate[((a) + (b)*(x)^(n))^(p), x]", "k ⋆ Subst[Integrate[x^(k - 1)*(a + b*x^(k*n))^p, x], x, x^(1/k)]", Hold[Simp[k ⋆ Subst[Int[x^(k - 1)*(a + b*x^(k*n))^p, x], x, x^(1/k)], x]]]] /; FreeQ[{a, b, p}, x] && FractionQ[n] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], Pattern[n, Blank[]]]]], Pattern[p, Blank[]]], Pattern[x, Blank[Symbol]]] := ShowStep[775, "If \!\(\*RowBox[{\"IGtQ\", \"[\", RowBox[{\"p\", \",\", \"0\"}], \"]\"}]\)", "Integrate[((a) + (b)*(x)^(n))^(p), x]", "Integrate[ExpandIntegrand[(a + b*x^n)^p, x], x]", Hold[Int[ExpandIntegrand[(a + b*x^n)^p, x], x]]] /; FreeQ[{a, b, n}, x] && IGtQ[p, 0] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], Pattern[n, Blank[]]]]], Pattern[p, Blank[]]], Pattern[x, Blank[Symbol]]] := ShowStep[776, "If \!\(\*RowBox[{\"EqQ\", \"[\", RowBox[{RowBox[{FractionBox[\"1\", \"n\"], \"+\", \"p\"}], \",\", \"0\"}], \"]\"}]\)", "Integrate[((a) + (b)*(x)^(n))^(p), x]", "x*(a + b*x^n)^p*((x^n/(a + b*x^n))^p/n) ⋆ Subst[Integrate[1/(x^(p + 1)*(1 - b*x)), x], x, x^n/(a + b*x^n)]", Hold[Simp[x*(a + b*x^n)^p*((x^n/(a + b*x^n))^p/n) ⋆ Subst[Int[1/(x^(p + 1)*(1 - b*x)), x], x, x^n/(a + b*x^n)], x]]] /; FreeQ[{a, b, n, p}, x] && EqQ[1/n + p, 0] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], Pattern[n, Blank[]]]]], Pattern[p, Blank[]]], Pattern[x, Blank[Symbol]]] := ShowStep[777, "If \!\(\*RowBox[{RowBox[{\"ILtQ\", \"[\", RowBox[{RowBox[{\"Simplify\", \"[\", RowBox[{FractionBox[\"1\", \"n\"], \"+\", \"p\", \"+\", \"1\"}], \"]\"}], \",\", \"0\"}], \"]\"}], \"&&\", RowBox[{\"NeQ\", \"[\", RowBox[{\"p\", \",\", RowBox[{\"-\", \"1\"}]}], \"]\"}]}]\)", "Integrate[((a) + (b)*(x)^(n))^(p), x]", "(-x)*((a + b*x^n)^(p + 1)/(a*n*(p + 1))) + (n*(p + 1) + 1)/(a*n*(p + 1)) ⋆ Integrate[(a + b*x^n)^(p + 1), x]", Hold[Simp[(-x)*((a + b*x^n)^(p + 1)/(a*n*(p + 1))), x] + Simp[(n*(p + 1) + 1)/(a*n*(p + 1)) ⋆ Int[(a + b*x^n)^(p + 1), x], x]]] /; FreeQ[{a, b, n, p}, x] && ILtQ[Simplify[1/n + p + 1], 0] && NeQ[p, -1] /; True
