Int[Times[Plus[Pattern[c, Blank[]], Times[Optional[Pattern[d, Blank[]]], Power[Pattern[x, Blank[]], 2]]], Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 8]]], Rational[-1, 2]]], Pattern[x, Blank[Symbol]]] := ShowStep[2423, "If \!\(\*RowBox[{\"NeQ\", \"[\", RowBox[{RowBox[{RowBox[{\"b\", \" \", SuperscriptBox[\"c\", \"4\"]}], \"-\", RowBox[{\"a\", \" \", SuperscriptBox[\"d\", \"4\"]}]}], \",\", \"0\"}], \"]\"}]\)", "Integrate[((c) + (d)*(x)^2)/Sqrt[(a) + (b)*(x)^8], x]", "(d + (b/a)^4^(-1)*c)/(2*(b/a)^4^(-1)) ⋆ Integrate[(1 + (b/a)^4^(-1)*x^2)/Sqrt[a + b*x^8], x] - (d - (b/a)^4^(-1)*c)/(2*(b/a)^4^(-1)) ⋆ Integrate[(1 - (b/a)^4^(-1)*x^2)/Sqrt[a + b*x^8], x]", Hold[Simp[(d + Rt[b/a, 4]*c)/(2*Rt[b/a, 4]) ⋆ Int[(1 + Rt[b/a, 4]*x^2)/Sqrt[a + b*x^8], x], x] - Simp[(d - Rt[b/a, 4]*c)/(2*Rt[b/a, 4]) ⋆ Int[(1 - Rt[b/a, 4]*x^2)/Sqrt[a + b*x^8], x], x]]] /; FreeQ[{a, b, c, d}, x] && NeQ[b*c^4 - a*d^4, 0] /; True
