Int[Power[E, Times[ArcSech[Pattern[u, Blank[]]], Optional[Pattern[n, Blank[]]]]], Pattern[x, Blank[Symbol]]] := ShowStep[6886, "If \!\(\*RowBox[{\"IntegerQ\", \"[\", \"n\", \"]\"}]\)", "Integrate[E^(ArcSech[u]*(n)), x]", "Integrate[(1/u + Sqrt[(1 - u)/(1 + u)] + (1/u)*Sqrt[(1 - u)/(1 + u)])^n, x]", Hold[Int[(1/u + Sqrt[(1 - u)/(1 + u)] + (1/u)*Sqrt[(1 - u)/(1 + u)])^n, x]]] /; IntegerQ[n] /; True
Int[Power[E, Times[ArcCsch[Pattern[u, Blank[]]], Optional[Pattern[n, Blank[]]]]], Pattern[x, Blank[Symbol]]] := ShowStep[6887, "If \!\(\*RowBox[{\"IntegerQ\", \"[\", \"n\", \"]\"}]\)", "Integrate[E^(ArcCsch[u]*(n)), x]", "Integrate[(1/u + Sqrt[1 + 1/u^2])^n, x]", Hold[Int[(1/u + Sqrt[1 + 1/u^2])^n, x]]] /; IntegerQ[n] /; True
Int[Times[Power[E, ArcSech[Times[Optional[Pattern[a, Blank[]]], Power[Pattern[x, Blank[]], Optional[Pattern[p, Blank[]]]]]]], Power[Pattern[x, Blank[]], -1]], Pattern[x, Blank[Symbol]]] := ShowStep[6888, "", "Integrate[E^ArcSech[(a)*(x)^(p)]/(x), x]", "-(a*p*x^p)^(-1) + (Sqrt[1 + a*x^p]/a)*Sqrt[1/(1 + a*x^p)] ⋆ Integrate[Sqrt[1 + a*x^p]*(Sqrt[1 - a*x^p]/x^(p + 1)), x]", Hold[-Simp[(a*p*x^p)^(-1), x] + Simp[(Sqrt[1 + a*x^p]/a)*Sqrt[1/(1 + a*x^p)] ⋆ Int[Sqrt[1 + a*x^p]*(Sqrt[1 - a*x^p]/x^(p + 1)), x], x]]] /; FreeQ[{a, p}, x] /; True
Int[Times[Power[E, ArcSech[Times[Optional[Pattern[a, Blank[]]], Power[Pattern[x, Blank[]], Optional[Pattern[p, Blank[]]]]]]], Power[Pattern[x, Blank[]], Optional[Pattern[m, Blank[]]]]], Pattern[x, Blank[Symbol]]] := ShowStep[6889, "If \!\(\*RowBox[{\"NeQ\", \"[\", RowBox[{\"m\", \",\", RowBox[{\"-\", \"1\"}]}], \"]\"}]\)", "Integrate[E^ArcSech[(a)*(x)^(p)]*(x)^(m), x]", "x^(m + 1)*(E^ArcSech[a*x^p]/(m + 1)) + (p/(a*(m + 1)) ⋆ Integrate[x^(m - p), x] + p*(Sqrt[1 + a*x^p]/(a*(m + 1)))*Sqrt[1/(1 + a*x^p)] ⋆ Integrate[x^(m - p)/(Sqrt[1 + a*x^p]*Sqrt[1 - a*x^p]), x])", Hold[Simp[x^(m + 1)*(E^ArcSech[a*x^p]/(m + 1)), x] + (Simp[p/(a*(m + 1)) ⋆ Int[x^(m - p), x], x] + Simp[p*(Sqrt[1 + a*x^p]/(a*(m + 1)))*Sqrt[1/(1 + a*x^p)] ⋆ Int[x^(m - p)/(Sqrt[1 + a*x^p]*Sqrt[1 - a*x^p]), x], x])]] /; FreeQ[{a, m, p}, x] && NeQ[m, -1] /; True
Int[Times[Power[E, ArcCsch[Times[Optional[Pattern[a, Blank[]]], Power[Pattern[x, Blank[]], Optional[Pattern[p, Blank[]]]]]]], Power[Pattern[x, Blank[]], Optional[Pattern[m, Blank[]]]]], Pattern[x, Blank[Symbol]]] := ShowStep[6890, "", "Integrate[E^ArcCsch[(a)*(x)^(p)]*(x)^(m), x]", "1/a ⋆ Integrate[x^(m - p), x] + Integrate[x^m*Sqrt[1 + 1/(a^2*x^(2*p))], x]", Hold[Simp[1/a ⋆ Int[x^(m - p), x], x] + Int[x^m*Sqrt[1 + 1/(a^2*x^(2*p))], x]]] /; FreeQ[{a, m, p}, x] /; True
Int[Times[Power[E, Times[ArcSech[Pattern[u, Blank[]]], Optional[Pattern[n, Blank[]]]]], Power[Pattern[x, Blank[]], Optional[Pattern[m, Blank[]]]]], Pattern[x, Blank[Symbol]]] := ShowStep[6891, "If \!\(\*RowBox[{\"IntegerQ\", \"[\", \"n\", \"]\"}]\)", "Integrate[E^(ArcSech[u]*(n))*(x)^(m), x]", "Integrate[x^m*(1/u + Sqrt[(1 - u)/(1 + u)] + (1/u)*Sqrt[(1 - u)/(1 + u)])^n, x]", Hold[Int[x^m*(1/u + Sqrt[(1 - u)/(1 + u)] + (1/u)*Sqrt[(1 - u)/(1 + u)])^n, x]]] /; FreeQ[m, x] && IntegerQ[n] /; True
