Int[Times[Power[E, ArcSech[Times[Optional[Pattern[c, Blank[]]], Pattern[x, Blank[]]]]], Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 2]]], -1]], Pattern[x, Blank[Symbol]]] := ShowStep[6893, "If \!\(\*RowBox[{\"EqQ\", \"[\", RowBox[{RowBox[{\"b\", \"+\", RowBox[{\"a\", \" \", SuperscriptBox[\"c\", \"2\"]}]}], \",\", \"0\"}], \"]\"}]\)", "Integrate[E^ArcSech[(c)*(x)]/((a) + (b)*(x)^2), x]", "1/(a*c) ⋆ Integrate[Sqrt[1/(1 + c*x)]/(x*Sqrt[1 - c*x]), x] + 1/c ⋆ Integrate[1/(x*(a + b*x^2)), x]", Hold[Simp[1/(a*c) ⋆ Int[Sqrt[1/(1 + c*x)]/(x*Sqrt[1 - c*x]), x], x] + Simp[1/c ⋆ Int[1/(x*(a + b*x^2)), x], x]]] /; FreeQ[{a, b, c}, x] && EqQ[b + a*c^2, 0] /; True
Int[Times[Power[E, ArcCsch[Times[Optional[Pattern[c, Blank[]]], Pattern[x, Blank[]]]]], Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 2]]], -1]], Pattern[x, Blank[Symbol]]] := ShowStep[6894, "If \!\(\*RowBox[{\"EqQ\", \"[\", RowBox[{RowBox[{\"b\", \"-\", RowBox[{\"a\", \" \", SuperscriptBox[\"c\", \"2\"]}]}], \",\", \"0\"}], \"]\"}]\)", "Integrate[E^ArcCsch[(c)*(x)]/((a) + (b)*(x)^2), x]", "1/(a*c^2) ⋆ Integrate[1/(x^2*Sqrt[1 + 1/(c^2*x^2)]), x] + 1/c ⋆ Integrate[1/(x*(a + b*x^2)), x]", Hold[Simp[1/(a*c^2) ⋆ Int[1/(x^2*Sqrt[1 + 1/(c^2*x^2)]), x], x] + Simp[1/c ⋆ Int[1/(x*(a + b*x^2)), x], x]]] /; FreeQ[{a, b, c}, x] && EqQ[b - a*c^2, 0] /; True
Int[Times[Power[E, ArcSech[Times[Optional[Pattern[c, Blank[]]], Pattern[x, Blank[]]]]], Power[Times[Optional[Pattern[d, Blank[]]], Pattern[x, Blank[]]], Optional[Pattern[m, Blank[]]]], Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 2]]], -1]], Pattern[x, Blank[Symbol]]] := ShowStep[6895, "If \!\(\*RowBox[{\"EqQ\", \"[\", RowBox[{RowBox[{\"b\", \"+\", RowBox[{\"a\", \" \", SuperscriptBox[\"c\", \"2\"]}]}], \",\", \"0\"}], \"]\"}]\)", "Integrate[(E^ArcSech[(c)*(x)]*((d)*(x))^(m))/((a) + (b)*(x)^2), x]", "d/(a*c) ⋆ Integrate[(d*x)^(m - 1)*(Sqrt[1/(1 + c*x)]/Sqrt[1 - c*x]), x] + d/c ⋆ Integrate[(d*x)^(m - 1)/(a + b*x^2), x]", Hold[Simp[d/(a*c) ⋆ Int[(d*x)^(m - 1)*(Sqrt[1/(1 + c*x)]/Sqrt[1 - c*x]), x], x] + Simp[d/c ⋆ Int[(d*x)^(m - 1)/(a + b*x^2), x], x]]] /; FreeQ[{a, b, c, d, m}, x] && EqQ[b + a*c^2, 0] /; True
Int[Times[Power[E, ArcCsch[Times[Optional[Pattern[c, Blank[]]], Pattern[x, Blank[]]]]], Power[Times[Optional[Pattern[d, Blank[]]], Pattern[x, Blank[]]], Optional[Pattern[m, Blank[]]]], Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[x, Blank[]], 2]]], -1]], Pattern[x, Blank[Symbol]]] := ShowStep[6896, "If \!\(\*RowBox[{\"EqQ\", \"[\", RowBox[{RowBox[{\"b\", \"-\", RowBox[{\"a\", \" \", SuperscriptBox[\"c\", \"2\"]}]}], \",\", \"0\"}], \"]\"}]\)", "Integrate[(E^ArcCsch[(c)*(x)]*((d)*(x))^(m))/((a) + (b)*(x)^2), x]", "d^2/(a*c^2) ⋆ Integrate[(d*x)^(m - 2)/Sqrt[1 + 1/(c^2*x^2)], x] + d/c ⋆ Integrate[(d*x)^(m - 1)/(a + b*x^2), x]", Hold[Simp[d^2/(a*c^2) ⋆ Int[(d*x)^(m - 2)/Sqrt[1 + 1/(c^2*x^2)], x], x] + Simp[d/c ⋆ Int[(d*x)^(m - 1)/(a + b*x^2), x], x]]] /; FreeQ[{a, b, c, d, m}, x] && EqQ[b - a*c^2, 0] /; True
Int[ArcSech[Pattern[u, Blank[]]], Pattern[x, Blank[Symbol]]] := ShowStep[6897, "If \!\(\*RowBox[{RowBox[{\"InverseFunctionFreeQ\", \"[\", RowBox[{\"u\", \",\", \"x\"}], \"]\"}], \"&&\", RowBox[{\"!\", RowBox[{\"FunctionOfExponentialQ\", \"[\", RowBox[{\"u\", \",\", \"x\"}], \"]\"}]}]}]\)", "Integrate[ArcSech[u], x]", "x*ArcSech[u] + Sqrt[1 - u^2]/(u*Sqrt[-1 + 1/u]*Sqrt[1 + 1/u]) ⋆ Integrate[SimplifyIntegrand[x*(D[u, x]/(u*Sqrt[1 - u^2])), x], x]", Hold[Simp[x*ArcSech[u], x] + Simp[Sqrt[1 - u^2]/(u*Sqrt[-1 + 1/u]*Sqrt[1 + 1/u]) ⋆ Int[SimplifyIntegrand[x*(D[u, x]/(u*Sqrt[1 - u^2])), x], x], x]]] /; InverseFunctionFreeQ[u, x] &&  !FunctionOfExponentialQ[u, x] /; True
Int[ArcCsch[Pattern[u, Blank[]]], Pattern[x, Blank[Symbol]]] := ShowStep[6898, "If \!\(\*RowBox[{RowBox[{\"InverseFunctionFreeQ\", \"[\", RowBox[{\"u\", \",\", \"x\"}], \"]\"}], \"&&\", RowBox[{\"!\", RowBox[{\"FunctionOfExponentialQ\", \"[\", RowBox[{\"u\", \",\", \"x\"}], \"]\"}]}]}]\)", "Integrate[ArcCsch[u], x]", "x*ArcCsch[u] - u/Sqrt[-u^2] ⋆ Integrate[SimplifyIntegrand[x*(D[u, x]/(u*Sqrt[-1 - u^2])), x], x]", Hold[Simp[x*ArcCsch[u], x] - Simp[u/Sqrt[-u^2] ⋆ Int[SimplifyIntegrand[x*(D[u, x]/(u*Sqrt[-1 - u^2])), x], x], x]]] /; InverseFunctionFreeQ[u, x] &&  !FunctionOfExponentialQ[u, x] /; True
Int[Times[Plus[Optional[Pattern[a, Blank[]]], Times[ArcSech[Pattern[u, Blank[]]], Optional[Pattern[b, Blank[]]]]], Power[Plus[Optional[Pattern[c, Blank[]]], Times[Optional[Pattern[d, Blank[]]], Pattern[x, Blank[]]]], Optional[Pattern[m, Blank[]]]]], Pattern[x, Blank[Symbol]]] := ShowStep[6899, "If \!\(\*RowBox[{RowBox[{\"NeQ\", \"[\", RowBox[{\"m\", \",\", RowBox[{\"-\", \"1\"}]}], \"]\"}], \"&&\", RowBox[{\"InverseFunctionFreeQ\", \"[\", RowBox[{\"u\", \",\", \"x\"}], \"]\"}], \"&&\", RowBox[{\"!\", RowBox[{\"FunctionOfQ\", \"[\", RowBox[{SuperscriptBox[RowBox[{\"(\", RowBox[{\"c\", \"+\", RowBox[{\"d\", \" \", \"x\"}]}], \")\"}], RowBox[{\"m\", \"+\", \"1\"}]], \",\", \"u\", \",\", \"x\"}], \"]\"}]}], \"&&\", RowBox[{\"!\", RowBox[{\"FunctionOfExponentialQ\", \"[\", RowBox[{\"u\", \",\", \"x\"}], \"]\"}]}]}]\)", "Integrate[((a) + ArcSech[u]*(b))*((c) + (d)*(x))^(m), x]", "(c + d*x)^(m + 1)*((a + b*ArcSech[u])/(d*(m + 1))) + b*(Sqrt[1 - u^2]/(d*(m + 1)*u*Sqrt[-1 + 1/u]*Sqrt[1 + 1/u])) ⋆ Integrate[SimplifyIntegrand[(c + d*x)^(m + 1)*(D[u, x]/(u*Sqrt[1 - u^2])), x], x]", Hold[Simp[(c + d*x)^(m + 1)*((a + b*ArcSech[u])/(d*(m + 1))), x] + Simp[b*(Sqrt[1 - u^2]/(d*(m + 1)*u*Sqrt[-1 + 1/u]*Sqrt[1 + 1/u])) ⋆ Int[SimplifyIntegrand[(c + d*x)^(m + 1)*(D[u, x]/(u*Sqrt[1 - u^2])), x], x], x]]] /; FreeQ[{a, b, c, d, m}, x] && NeQ[m, -1] && InverseFunctionFreeQ[u, x] &&  !FunctionOfQ[(c + d*x)^(m + 1), u, x] &&  !FunctionOfExponentialQ[u, x] /; True
Int[Times[Plus[Optional[Pattern[a, Blank[]]], Times[ArcCsch[Pattern[u, Blank[]]], Optional[Pattern[b, Blank[]]]]], Power[Plus[Optional[Pattern[c, Blank[]]], Times[Optional[Pattern[d, Blank[]]], Pattern[x, Blank[]]]], Optional[Pattern[m, Blank[]]]]], Pattern[x, Blank[Symbol]]] := ShowStep[6900, "If \!\(\*RowBox[{RowBox[{\"NeQ\", \"[\", RowBox[{\"m\", \",\", RowBox[{\"-\", \"1\"}]}], \"]\"}], \"&&\", RowBox[{\"InverseFunctionFreeQ\", \"[\", RowBox[{\"u\", \",\", \"x\"}], \"]\"}], \"&&\", RowBox[{\"!\", RowBox[{\"FunctionOfQ\", \"[\", RowBox[{SuperscriptBox[RowBox[{\"(\", RowBox[{\"c\", \"+\", RowBox[{\"d\", \" \", \"x\"}]}], \")\"}], RowBox[{\"m\", \"+\", \"1\"}]], \",\", \"u\", \",\", \"x\"}], \"]\"}]}], \"&&\", RowBox[{\"!\", RowBox[{\"FunctionOfExponentialQ\", \"[\", RowBox[{\"u\", \",\", \"x\"}], \"]\"}]}]}]\)", "Integrate[((a) + ArcCsch[u]*(b))*((c) + (d)*(x))^(m), x]", "(c + d*x)^(m + 1)*((a + b*ArcCsch[u])/(d*(m + 1))) - b*(u/(d*(m + 1)*Sqrt[-u^2])) ⋆ Integrate[SimplifyIntegrand[(c + d*x)^(m + 1)*(D[u, x]/(u*Sqrt[-1 - u^2])), x], x]", Hold[Simp[(c + d*x)^(m + 1)*((a + b*ArcCsch[u])/(d*(m + 1))), x] - Simp[b*(u/(d*(m + 1)*Sqrt[-u^2])) ⋆ Int[SimplifyIntegrand[(c + d*x)^(m + 1)*(D[u, x]/(u*Sqrt[-1 - u^2])), x], x], x]]] /; FreeQ[{a, b, c, d, m}, x] && NeQ[m, -1] && InverseFunctionFreeQ[u, x] &&  !FunctionOfQ[(c + d*x)^(m + 1), u, x] &&  !FunctionOfExponentialQ[u, x] /; True
Int[Times[Plus[Optional[Pattern[a, Blank[]]], Times[ArcSech[Pattern[u, Blank[]]], Optional[Pattern[b, Blank[]]]]], Pattern[v, Blank[]]], Pattern[x, Blank[Symbol]]] := With[{w = IntHide[v, x]}, ShowStep[6901, "If \!\(\*RowBox[{RowBox[{\"InverseFunctionFreeQ\", \"[\", RowBox[{\"u\", \",\", \"x\"}], \"]\"}], \"&&\", RowBox[{\"!\", RowBox[{\"MatchQ\", \"[\", RowBox[{\"v\", \",\", RowBox[{SuperscriptBox[RowBox[{\"(\", RowBox[{\"c_.\", \"+\", RowBox[{\"d_.\", \" \", \"x\"}]}], \")\"}], \"m_.\"], \"/;\", RowBox[{\"FreeQ\", \"[\", RowBox[{RowBox[{\"{\", RowBox[{\"c\", \",\", \"d\", \",\", \"m\"}], \"}\"}], \",\", \"x\"}], \"]\"}]}]}], \"]\"}]}]}]\) let \!\(\*RowBox[{\"w\", \"=\", RowBox[{\"IntHide\", \"[\", RowBox[{\"v\", \",\", \"x\"}], \"]\"}]}]\), then if \!\(\*RowBox[{\"InverseFunctionFreeQ\", \"[\", RowBox[{\"w\", \",\", \"x\"}], \"]\"}]\)", "Integrate[((a) + ArcSech[u]*(b))*(v), x]", "(a + b*ArcSech[u]) ⋆ w + b*(Sqrt[1 - u^2]/(u*Sqrt[-1 + 1/u]*Sqrt[1 + 1/u])) ⋆ Integrate[SimplifyIntegrand[w*(D[u, x]/(u*Sqrt[1 - u^2])), x], x]", Hold[Simp[(a + b*ArcSech[u]) ⋆ w, x] + Simp[b*(Sqrt[1 - u^2]/(u*Sqrt[-1 + 1/u]*Sqrt[1 + 1/u])) ⋆ Int[SimplifyIntegrand[w*(D[u, x]/(u*Sqrt[1 - u^2])), x], x], x]]] /; InverseFunctionFreeQ[w, x]] /; FreeQ[{a, b}, x] && InverseFunctionFreeQ[u, x] &&  !MatchQ[v, ((c_.) + (d_.)*x)^(m_.) /; FreeQ[{c, d, m}, x]] /; True
Int[Times[Plus[Optional[Pattern[a, Blank[]]], Times[ArcCsch[Pattern[u, Blank[]]], Optional[Pattern[b, Blank[]]]]], Pattern[v, Blank[]]], Pattern[x, Blank[Symbol]]] := With[{w = IntHide[v, x]}, ShowStep[6902, "If \!\(\*RowBox[{RowBox[{\"InverseFunctionFreeQ\", \"[\", RowBox[{\"u\", \",\", \"x\"}], \"]\"}], \"&&\", RowBox[{\"!\", RowBox[{\"MatchQ\", \"[\", RowBox[{\"v\", \",\", RowBox[{SuperscriptBox[RowBox[{\"(\", RowBox[{\"c_.\", \"+\", RowBox[{\"d_.\", \" \", \"x\"}]}], \")\"}], \"m_.\"], \"/;\", RowBox[{\"FreeQ\", \"[\", RowBox[{RowBox[{\"{\", RowBox[{\"c\", \",\", \"d\", \",\", \"m\"}], \"}\"}], \",\", \"x\"}], \"]\"}]}]}], \"]\"}]}]}]\) let \!\(\*RowBox[{\"w\", \"=\", RowBox[{\"IntHide\", \"[\", RowBox[{\"v\", \",\", \"x\"}], \"]\"}]}]\), then if \!\(\*RowBox[{\"InverseFunctionFreeQ\", \"[\", RowBox[{\"w\", \",\", \"x\"}], \"]\"}]\)", "Integrate[((a) + ArcCsch[u]*(b))*(v), x]", "(a + b*ArcCsch[u]) ⋆ w - b*(u/Sqrt[-u^2]) ⋆ Integrate[SimplifyIntegrand[w*(D[u, x]/(u*Sqrt[-1 - u^2])), x], x]", Hold[Simp[(a + b*ArcCsch[u]) ⋆ w, x] - Simp[b*(u/Sqrt[-u^2]) ⋆ Int[SimplifyIntegrand[w*(D[u, x]/(u*Sqrt[-1 - u^2])), x], x], x]]] /; InverseFunctionFreeQ[w, x]] /; FreeQ[{a, b}, x] && InverseFunctionFreeQ[u, x] &&  !MatchQ[v, ((c_.) + (d_.)*x)^(m_.) /; FreeQ[{c, d, m}, x]] /; True
Int[Erf[Plus[Optional[Pattern[a, Blank[]]], Times[Optional[Pattern[b, Blank[]]], Pattern[x, Blank[]]]]], Pattern[x, Blank[Symbol]]] := ShowStep[6903, "", "Integrate[Erf[(a) + (b)*(x)], x]", "(a + b*x)*(Erf[a + b*x]/b) + 1/(b*Sqrt[Pi]*E^(a + b*x)^2)", Hold[Simp[(a + b*x)*(Erf[a + b*x]/b), x] + Simp[1/(b*Sqrt[Pi]*E^(a + b*x)^2), x]]] /; FreeQ[{a, b}, x] /; True
Int[Erfc[Plus[Optional[Pattern[a, Blank[]]], Times[Optional[Pattern[b, Blank[]]], Pattern[x, Blank[]]]]], Pattern[x, Blank[Symbol]]] := ShowStep[6904, "", "Integrate[Erfc[(a) + (b)*(x)], x]", "(a + b*x)*(Erfc[a + b*x]/b) - 1/(b*Sqrt[Pi]*E^(a + b*x)^2)", Hold[Simp[(a + b*x)*(Erfc[a + b*x]/b), x] - Simp[1/(b*Sqrt[Pi]*E^(a + b*x)^2), x]]] /; FreeQ[{a, b}, x] /; True
Int[Erfi[Plus[Optional[Pattern[a, Blank[]]], Times[Optional[Pattern[b, Blank[]]], Pattern[x, Blank[]]]]], Pattern[x, Blank[Symbol]]] := ShowStep[6905, "", "Integrate[Erfi[(a) + (b)*(x)], x]", "(a + b*x)*(Erfi[a + b*x]/b) - E^(a + b*x)^2/(b*Sqrt[Pi])", Hold[Simp[(a + b*x)*(Erfi[a + b*x]/b), x] - Simp[E^(a + b*x)^2/(b*Sqrt[Pi]), x]]] /; FreeQ[{a, b}, x] /; True
Int[Power[Erf[Plus[Optional[Pattern[a, Blank[]]], Times[Optional[Pattern[b, Blank[]]], Pattern[x, Blank[]]]]], 2], Pattern[x, Blank[Symbol]]] := ShowStep[6906, "", "Integrate[Erf[(a) + (b)*(x)]^2, x]", "(a + b*x)*(Erf[a + b*x]^2/b) - 4/Sqrt[Pi] ⋆ Integrate[(a + b*x)*(Erf[a + b*x]/E^(a + b*x)^2), x]", Hold[Simp[(a + b*x)*(Erf[a + b*x]^2/b), x] - Simp[4/Sqrt[Pi] ⋆ Int[(a + b*x)*(Erf[a + b*x]/E^(a + b*x)^2), x], x]]] /; FreeQ[{a, b}, x] /; True
Int[Power[Erfc[Plus[Optional[Pattern[a, Blank[]]], Times[Optional[Pattern[b, Blank[]]], Pattern[x, Blank[]]]]], 2], Pattern[x, Blank[Symbol]]] := ShowStep[6907, "", "Integrate[Erfc[(a) + (b)*(x)]^2, x]", "(a + b*x)*(Erfc[a + b*x]^2/b) + 4/Sqrt[Pi] ⋆ Integrate[(a + b*x)*(Erfc[a + b*x]/E^(a + b*x)^2), x]", Hold[Simp[(a + b*x)*(Erfc[a + b*x]^2/b), x] + Simp[4/Sqrt[Pi] ⋆ Int[(a + b*x)*(Erfc[a + b*x]/E^(a + b*x)^2), x], x]]] /; FreeQ[{a, b}, x] /; True
Int[Power[Erfi[Plus[Optional[Pattern[a, Blank[]]], Times[Optional[Pattern[b, Blank[]]], Pattern[x, Blank[]]]]], 2], Pattern[x, Blank[Symbol]]] := ShowStep[6908, "", "Integrate[Erfi[(a) + (b)*(x)]^2, x]", "(a + b*x)*(Erfi[a + b*x]^2/b) - 4/Sqrt[Pi] ⋆ Integrate[(a + b*x)*E^(a + b*x)^2*Erfi[a + b*x], x]", Hold[Simp[(a + b*x)*(Erfi[a + b*x]^2/b), x] - Simp[4/Sqrt[Pi] ⋆ Int[(a + b*x)*E^(a + b*x)^2*Erfi[a + b*x], x], x]]] /; FreeQ[{a, b}, x] /; True
