Int[Pattern[u, Blank[]], Pattern[x, Blank[Symbol]]] := With[{lst = FunctionOfLinear[u, x]}, ShowStep["", "Int[F[a+b*x],x]", "Subst[Int[F[x],x],x,a+b*x]/b", Hold[Simp[1/lst[[3]] ⋆ Subst[Int[lst[[1]], x], x, lst[[2]] + lst[[3]]*x], x]]] /;  !FalseQ[lst]] /; True
Int[Times[Pattern[u, Blank[]], Power[Pattern[x, Blank[]], -1]], Pattern[x, Blank[Symbol]]] := With[{lst = PowerVariableExpn[u, 0, x]}, ShowStep["", "Int[F[(c*x)^n]/x,x]", "Subst[Int[F[x]/x,x],x,(c*x)^n]/n", Hold[Simp[1/lst[[2]] ⋆ Subst[Int[NormalizeIntegrand[Simplify[lst[[1]]/x], x], x], x, (lst[[3]]*x)^lst[[2]]], x]]] /;  !FalseQ[lst] && NeQ[lst[[2]], 0]] /; True && NonsumQ[u] &&  !RationalFunctionQ[u, x]
Int[Times[Pattern[u, Blank[]], Power[Pattern[x, Blank[]], Optional[Pattern[m, Blank[]]]]], Pattern[x, Blank[Symbol]]] := With[{lst = PowerVariableExpn[u, m + 1, x]}, ShowStep["If g=GCD[m+1,n]>1,", "Int[x^m*F[x^n],x]", "1/g ⋆ Subst[Int[x^((m+1)/g-1)*F[x^(n/g)],x],x,x^g]", Hold[Simp[1/lst[[2]] ⋆ Subst[Int[NormalizeIntegrand[Simplify[lst[[1]]/x], x], x], x, (lst[[3]]*x)^lst[[2]]], x]]] /;  !FalseQ[lst] && NeQ[lst[[2]], m + 1]] /; True && IntegerQ[m] && NeQ[m, -1] && NonsumQ[u] && (GtQ[m, 0] ||  !AlgebraicFunctionQ[u, x])
Int[Times[Pattern[Fx, Blank[]], Power[Pattern[x, Blank[]], Pattern[m, Blank[]]]], Pattern[x, Blank[Symbol]]] := With[{k = Denominator[m]}, ShowStep[7284, "If \!\(\*RowBox[{\"FractionQ\", \"[\", \"m\", \"]\"}]\) let \!\(\*RowBox[{\"k\", \"=\", RowBox[{\"Denominator\", \"[\", \"m\", \"]\"}]}]\), then", "Integrate[(Fx)*(x)^(m), x]", "k ⋆ Subst[Integrate[x^(k*(m + 1) - 1)*SubstPower[Fx, x, k], x], x, x^(1/k)]", Hold[Simp[k ⋆ Subst[Int[x^(k*(m + 1) - 1)*SubstPower[Fx, x, k], x], x, x^(1/k)], x]]]] /; FractionQ[m] /; True
Int[Pattern[u, Blank[]], Pattern[x, Blank[Symbol]]] := With[{lst = FunctionOfSquareRootOfQuadratic[u, x]}, ShowStep["", "Int[F[Sqrt[a+b*x+c*x^2],x],x]", "2 ⋆ Subst[Int[F[(c*Sqrt[a]-b*x+Sqrt[a]*x^2)/(c-x^2),(-b+2*Sqrt[a]*x)/(c-x^2)]*\n\t\t\t\t(c*Sqrt[a]-b*x+Sqrt[a]*x^2)/(c-x^2)^2,x],x,(-Sqrt[a]+Sqrt[a+b*x+c*x^2])/x]", Hold[Simp[2 ⋆ Subst[Int[lst[[1]], x], x, lst[[2]]], x]]] /;  !FalseQ[lst] && EqQ[lst[[3]], 1]] /; True && EulerIntegrandQ[u, x]
Int[Pattern[u, Blank[]], Pattern[x, Blank[Symbol]]] := With[{lst = FunctionOfSquareRootOfQuadratic[u, x]}, ShowStep["", "Int[F[Sqrt[a+b*x+c*x^2],x],x]", "2 ⋆ Subst[Int[F[(a*Sqrt[c]+b*x+Sqrt[c]*x^2)/(b+2*Sqrt[c]*x),(-a+x^2)/(b+2*Sqrt[c]*x)]*\n\t\t\t\t(a*Sqrt[c]+b*x+Sqrt[c]*x^2)/(b+2*Sqrt[c]*x)^2,x],x,Sqrt[c]*x+Sqrt[a+b*x+c*x^2]]", Hold[Simp[2 ⋆ Subst[Int[lst[[1]], x], x, lst[[2]]], x]]] /;  !FalseQ[lst] && EqQ[lst[[3]], 2]] /; True && EulerIntegrandQ[u, x]
Int[Pattern[u, Blank[]], Pattern[x, Blank[Symbol]]] := With[{lst = FunctionOfSquareRootOfQuadratic[u, x]}, ShowStep["", "Int[F[Sqrt[a+b*x+c*x^2],x],x]", "-2*Sqrt[b^2-4*a*c] ⋆ Subst[Int[F[-Sqrt[b^2-4*a*c]*x/(c-x^2),\n\t\t\t  (b*c+c*Sqrt[b^2-4*a*c]+(-b+Sqrt[b^2-4*a*c])*x^2)/(-2*c*(c-x^2))]*x/(c-x^2)^2,x],\n\t\t\t   x,2*c*Sqrt[a+b*x+c*x^2]/(b-Sqrt[b^2-4*a*c]+2*c*x)]", Hold[Simp[2 ⋆ Subst[Int[lst[[1]], x], x, lst[[2]]], x]]] /;  !FalseQ[lst] && EqQ[lst[[3]], 3]] /; True && EulerIntegrandQ[u, x]
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[v, Blank[]], 2]]], -1], Pattern[x, Blank[Symbol]]] := ShowStep[7288, "", "Integrate[((a) + (b)*(v)^2)^(-1), x]", "1/(2*a) ⋆ Integrate[Together[1/(1 - v/Sqrt[-a/b])], x] + 1/(2*a) ⋆ Integrate[Together[1/(1 + v/Sqrt[-a/b])], x]", Hold[Simp[1/(2*a) ⋆ Int[Together[1/(1 - v/Rt[-a/b, 2])], x], x] + Simp[1/(2*a) ⋆ Int[Together[1/(1 + v/Rt[-a/b, 2])], x], x]]] /; FreeQ[{a, b}, x] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[v, Blank[]], Pattern[n, Blank[]]]]], -1], Pattern[x, Blank[Symbol]]] := ShowStep[7289, "If \!\(\*RowBox[{\"IGtQ\", \"[\", RowBox[{FractionBox[\"n\", \"2\"], \",\", \"1\"}], \"]\"}]\)", "Integrate[((a) + (b)*(v)^(n))^(-1), x]", "2/(a*n) ⋆ Sum[Integrate[Together[1/(1 - v^2/((-1)^(4*(k/n))*(-a/b)^(n/2)^(-1)))], x], {k, 1, n/2}]", Hold[Simp[2/(a*n) ⋆ Sum[Int[Together[1/(1 - v^2/((-1)^(4*(k/n))*Rt[-a/b, n/2]))], x], {k, 1, n/2}], x]]] /; FreeQ[{a, b}, x] && IGtQ[n/2, 1] /; True
Int[Power[Plus[Pattern[a, Blank[]], Times[Optional[Pattern[b, Blank[]]], Power[Pattern[v, Blank[]], Pattern[n, Blank[]]]]], -1], Pattern[x, Blank[Symbol]]] := ShowStep[7290, "If \!\(\*RowBox[{\"IGtQ\", \"[\", RowBox[{FractionBox[RowBox[{\"n\", \"-\", \"1\"}], \"2\"], \",\", \"0\"}], \"]\"}]\)", "Integrate[((a) + (b)*(v)^(n))^(-1), x]", "1/(a*n) ⋆ Sum[Integrate[Together[1/(1 - v/((-1)^(2*(k/n))*(-a/b)^n^(-1)))], x], {k, 1, n}]", Hold[Simp[1/(a*n) ⋆ Sum[Int[Together[1/(1 - v/((-1)^(2*(k/n))*Rt[-a/b, n]))], x], {k, 1, n}], x]]] /; FreeQ[{a, b}, x] && IGtQ[(n - 1)/2, 0] /; True
